40	function sourceFiles(directory: string): string[] {
41	  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
42	    const path = join(directory, entry.name);
43	    if (entry.isDirectory()) return sourceFiles(path);
44	    return /\.(ts|tsx|js|mjs|cjs)$/.test(entry.name) ? [path] : [];
45	  });
46	}
47	
48	/** Source without comments or string contents, so that prose mentioning a forbidden call is not a violation. */
49	function code(source: string): string {
50	  return source
51	    .replace(/\/\*[\s\S]*?\*\//g, "")
52	    .replace(/(^|[^:])\/\/.*$/gm, "$1")
53	    .replace(/(["'`])(?:\\.|(?!\1)[^\\\n])*\1/g, '""');
54	}
55	
56	function importedModules(source: string): string[] {
57	  const specifiers: string[] = [];
58	  const patterns = [
59	    /\bimport\s+(?:type\s+)?(?:[\w*{}\s,$]+\s+from\s+)?["']([^"']+)["']/g,
60	    /\bexport\s+(?:type\s+)?[\w*{}\s,$]+\s+from\s+["']([^"']+)["']/g,
61	    /\bimport\s*\(\s*["']([^"']+)["']\s*\)/g,
62	    /\brequire\s*\(\s*["']([^"']+)["']\s*\)/g,
63	  ];
64	  for (const pattern of patterns) for (const match of source.matchAll(pattern)) specifiers.push(match[1]!);
65	  return specifiers;
66	}
67	
68	function violations(source: string): string[] {
69	  const found = importedModules(source)
70	    .filter((specifier) => FORBIDDEN_MODULES.some((pattern) => pattern.test(specifier)))
71	    .map((specifier) => `imports ${specifier}`);
72	  const stripped = code(source);
73	  for (const [pattern, label] of FORBIDDEN_CALLS) if (pattern.test(stripped)) found.push(`uses ${label}`);
74	  return found;
75	}
76	
77	describe("purity rule", () => {
78	  it("catches each forbidden dependency in a sample", () => {
79	    expect(violations('import Phaser from "phaser";')).toEqual(["imports phaser"]);
