12	
13	/** Turns a protocol axis in [-1, 1] into simulation units. Out-of-range values clamp; anything non-finite is 0. */
14	export function quantizeAxis(axis: number): number {
15	  if (!Number.isFinite(axis)) return 0;
16	  const clamped = axis < -1 ? -1 : axis > 1 ? 1 : axis;
17	  return Math.round(clamped * AXIS_SCALE);
